def pollard_rho(n):
  if n%2==0: return 2
  while True:
    c = randint(1, n-1)
    y = randint(0, n-1); r = 1; q = 1; g = 1; m = 128
    while g == 1:
      x = y
      for _ in range(r): y = f(y,c,n)
      k = 0
      while k < r and g == 1:
        ys = y
        for _ in range(min(m, r-k)):
          y = f(y,c,n); q = q*abs(x-y) % n
        g = gcd(q, n); k += m
      r <<= 1
    if g == n:   # 回退逐个检查
      g = 1
      while g == 1:
        ys = f(ys,c,n); g = gcd(abs(x-ys), n)
      if g == n: continue
    return g

def factor(n):
  if is_prime(n): return [n]
  d = pollard_rho(n)
  return factor(d) + factor(n//d)
